class WrongActivationStatus(Exception):
    """
    Raised when not all cpri link activation statuses on capacity units are correct.
    """


class WrongSoapUpdateStatus(Exception):
    """Raised when soap update status of parameter will differ from 'ok'."""


class ContainerIsNotPresent(Exception):
    """
    Raised when container asked by user is not present on device unit.
    """


class TargetBdError(Exception):
    """
    Raised when TargetBD has wrong content.
    """


class RadioUnitIpNotReachable(Exception):
    """
    Raised when radio unit IP is not reachable in container.
    """


class UnknownCommandContent(Exception):
    """
    Raised when executed command returns response that is not known and implementation needs to be done.
    """


class BBMODInformationNotFound(Exception):
    """
    Raised when particular baseband module information is not found.
    """


class CommandError(Exception):
    """
    Raised when command execution has failed.
    """
    pass


class NodeIDNotSupported(Exception):
    """
    Raised when provided NodeID is not supported.
    """
    pass
